function CAP(ext: string): int
    reads
    ensures 0 <= result <= |ext|
{
    var count := 0;
    var i := 0;
    while (i < |ext|)
        invariant 0 <= i <= |ext|
        invariant count == CountUpperCase(ext, 0, i)
    {
        if (IsUpper(ext[i])) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function SM(ext: string): int
    reads
    ensures 0 <= result <= |ext|
{
    var count := 0;
    var i := 0;
    while (i < |ext|)
        invariant 0 <= i <= |ext|
        invariant count == CountLowerCase(ext, 0, i)
    {
        if (IsLower(ext[i])) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function CountUpperCase(ext: string, start: int, end: int): int
    ensures 0 <= start <= end <= |ext|
{
    var count := 0;
    var i := start;
    while (i < end)
        invariant start <= i <= end
        invariant count == CountUpperCasesInRange(ext, start, i)
    {
        if (IsUpper(ext[i])) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function CountLowerCase(ext: string, start: int, end: int): int
    ensures 0 <= start <= end <= |ext|
{
    var count := 0;
    var i := start;
    while (i < end)
        invariant start <= i <= end
        invariant count == CountLowerCasesInRange(ext, start, i)
    {
        if (IsLower(ext[i])) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function IsUpper(c: char): bool
{
    return c >= 'A' && c <= 'Z';
}

function IsLower(c: char): bool
{
    return c >= 'a' && c <= 'z';
}
